// Validate and prepare export request.
const body = $json.body || {};
const datasetId = body.dataset_id;
const jobId = body.job_id;
const minQuality = body.min_quality || 0.6;
const limit = body.limit || 10000;

if (!datasetId) {
  throw new Error('dataset_id is required');
}

return [{ json: { dataset_id: datasetId, job_id: jobId, min_quality: minQuality, limit } }];

// Convert RPC result to JSONL format.
// Each row has: {example_id, example_type, jsonl_row}
const rows = Array.isArray($json) ? $json : [$json];
const allRows = rows.flatMap(r => Array.isArray(r) ? r : [r]);

const sftLines = [];
const dpoLines = [];

for (const row of allRows) {
  const jsonlRow = row.jsonl_row;
  if (!jsonlRow) continue;

  if (row.example_type === 'preference_pair') {
    dpoLines.push(JSON.stringify(jsonlRow));
  } else {
    sftLines.push(JSON.stringify(jsonlRow));
  }
}

const sftContent = sftLines.join('\n');
const dpoContent = dpoLines.join('\n');

return [{
  json: {
    dataset_id: $('Validate Request').first().json.dataset_id,
    job_id: $('Validate Request').first().json.job_id,
    sft_count: sftLines.length,
    dpo_count: dpoLines.length,
    total: sftLines.length + dpoLines.length,
    sft_jsonl: sftContent,
    dpo_jsonl: dpoContent
  }
}];

// Return export result as webhook response.
const data = $json;

return [{
  json: {
    success: true,
    dataset_id: data.dataset_id,
    job_id: data.job_id,
    sft_count: data.sft_count,
    dpo_count: data.dpo_count,
    total: data.total,
    sft_jsonl: data.sft_jsonl,
    dpo_jsonl: data.dpo_jsonl
  }
}];
